import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"3.0.0-WP06g2 — L1 localization + the system IME","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/3.0.0-WP06g2.md","filePath":"zh/release/3.0.0-WP06g2.md"}'),r={name:"zh/release/3.0.0-WP06g2.md"};function n(i,e,c,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-0-0-wp06g2-—-l1-localization-the-system-ime" tabindex="-1">3.0.0-WP06g2 — L1 localization + the system IME <a class="header-anchor" href="#_3-0-0-wp06g2-—-l1-localization-the-system-ime" aria-label="Permalink to &quot;3.0.0-WP06g2 — L1 localization + the system IME&quot;">​</a></h1><p>The l1_i18n batch: the ring-3 world goes bilingual, and Chinese input becomes a system service.</p><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><ul><li><strong>The i18n framework.</strong> Every one of the 274 ring-3 programs carries <code>i18n/en.json</code> + <code>i18n/zh.json</code> (folder apps in <code>src/L1/&lt;name&gt;/i18n/</code>, legacy flat programs under <code>src/L1/_i18n/&lt;name&gt;/</code>). The resources compile into per-app key-sorted tables (<code>gen_userprogs.py</code>, strict gate - a missing resource fails the build); <code>_shared/i18n.h</code> provides the <code>tr_()</code> runtime (one <code>L1SVC DISP/LANG_GET</code> probe per process, zh-miss falls back to en, en-miss to the key). The L0 side keeps one shared table (<code>etc/i18n/l0/{en,zh}.json</code> → <code>tools/gen_l0_i18n.py</code>). Nothing is hardcoded: the sources say <code>tr_(&quot;key&quot;)</code>, the resource files carry the text.</li><li><strong><code>lang zh</code> is real now.</strong> The historical zh columns of the five <code>lang</code> messages were English placeholders since the v2.2.0 rescue - they render real Chinese now. <code>help -a</code> shows the Chinese registry hints for all 274 programs; the shell built-ins, the file tools (usage/error sentences), <code>stat</code>, <code>free</code>, <code>ps</code>, <code>date</code> follow the zh_CN convention (translated sentences, English column skeletons).</li><li><strong>The system IME.</strong> One engine + one session live in the L0 display service (<code>ime_session.c</code>); editors drive it through the new <code>L1SVC_DISP_IME_BEGIN/KEY/END</code> ops (13/14/15, appended per the numbering contract) and never embed a copy. Candidates are phrase-first (622 hand-authored high-frequency words, pooled table), then the single characters (all 3755 level-1 hanzi), then one smart compose candidate (the first 2-3 segment exact-syllable split). Nine per page; PageUp/PageDown (or <code>-</code>/<code>=</code>) page; digits 1-9 pick; space picks first; Enter commits the raw letters; Esc clears. <code>ime -i</code> (the interactive console compose line) runs the same engine.</li><li><strong>The editors.</strong> <code>editor_core.h</code> is UTF-8 glyph-aware (character motion, whole-glyph deletion with exact cell wipes, multi-byte insert), gains <code>^K</code> cut / <code>^R</code> copy / <code>^U</code> paste, and F2 toggles the system IME (the compose strip renders on the status line). <code>vi</code> is modal for real: CMD mode (<code>hjkl</code>, <code>x</code>, <code>dd</code>, <code>yy</code>, <code>p</code>, <code>i/a/o</code>, <code>:w/:q/:wq/:q!</code>) over the same engine.</li><li><strong>The make-all gap closed.</strong> <code>userprogs_data.h</code> is a real make target (see KNOWN_ISSUES); the i18n json files ride the staleness set too.</li></ul><h2 id="live-caught-on-the-way" tabindex="-1">Live-caught on the way <a class="header-anchor" href="#live-caught-on-the-way" aria-label="Permalink to &quot;Live-caught on the way&quot;">​</a></h2><p>The phrase pool had no NUL separators (the generator counted +1 but never appended them - the whole library silently never matched); the phrase binary search broke length ties in the wrong direction; the smart compose outranked the real characters; <code>l1_l1_dispatch</code> never NUL-terminated its rendering (strlen ran ~100 bytes into the heap past every <code>help -a</code>); ush&#39;s own help buffer stayed 8 KiB; the serial CSI table lacked the xterm F-key sequences (F2 was unreachable from real terminals - raw 0x90..0x9B never arrives over serial).</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>i18n battery 7/7, IME battery 3/3, editor battery 10/10, per-program hints battery 4/4 (all 274 Chinese hints byte-scanned), the WP06g1 regression set (chinesetest 81/81, V4/V4b/V5, font audit 6763+682) all green on the final image.</p>',8)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
